import React, { useCallback, useState } from 'react';
import type { ColDef, ValueGetterParams, GridReadyEvent } from 'ag-grid-community';
import { AllCommunityModule } from 'ag-grid-community';
import { AgGridProvider, AgGridReact } from 'ag-grid-react';

interface IRow {
  barang: string;
  lokasi: number;
  isi: number;
  tapel: number;
  tinggi: number;
  col0: number;
  total?: number;
  col6: string;
  omega: string;
  a: string;
  cttn: string;
}

const GridExample = () => {
  const [rowData] = useState<IRow[]>([
    { barang: 'Kabel', lokasi: 1, isi: 10, tapel: 2024, tinggi: 150, col0: 0, col6: '6', omega: 'Ω1', a: 'A', cttn: 'Baik' },
    { barang: 'Pipa', lokasi: 2, isi: 20, tapel: 2023, tinggi: 200, col0: 0, col6: '6', omega: 'Ω2', a: 'B', cttn: 'Rusak' },
    { barang: 'Baut', lokasi: 3, isi: 100, tapel: 2025, tinggi: 5, col0: 0, col6: '6', omega: 'Ω3', a: 'C', cttn: '-' },
  ]);

  const [colDefs] = useState<ColDef<IRow>[]>([
    { field: 'barang', headerName: 'Barang' },
    { field: 'lokasi', headerName: 'Lokasi', cellDataType: 'number' },
    { field: 'isi', headerName: 'Isi', cellDataType: 'number' },
    { field: 'tapel', headerName: 'Tapel', cellDataType: 'number' },
    { field: 'tinggi', headerName: 'Tinggi', cellDataType: 'number' },
    { field: 'col0', headerName: '0', cellDataType: 'number' },
    {
      field: 'total',
      headerName: 'Total',
      editable: false,
      valueGetter: (params: ValueGetterParams<IRow>) => {
        const tapel = params.data?.tapel ?? 0;
        const tinggi = params.data?.tinggi ?? 0;
        const col0 = params.data?.col0 ?? 0;
        return tapel * tinggi + col0;
      },
    },
    { field: 'col6', headerName: '6' },
    { field: 'omega', headerName: 'Omega' },
    { field: 'a', headerName: 'a' },
    { field: 'cttn', headerName: 'Cttn' },
  ]);

  const defaultColDef: ColDef = {
    editable: true,
    resizable: true,
  };

  const onGridReady = useCallback((params: GridReadyEvent) => {
    params.api.autoSizeAllColumns();
  }, []);

  return (
    <AgGridProvider modules={[AllCommunityModule]}>
      <div className="grid-container">
        <AgGridReact
          rowData={rowData}
          columnDefs={colDefs}
          defaultColDef={defaultColDef}
          autoSizeStrategy={{ type: 'fitCellContents' }}
          onGridReady={onGridReady}
        />
      </div>
    </AgGridProvider>
  );
};

export default GridExample;
